import java.util.Scanner;

public class TextAnalysis {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int length = sc.nextInt();
        String str = sc.next();
        sc.close();

        int maxOutside = 0, maxInside = 0, outsideCount = 0, insideCount = 0;
        boolean insideParen = false;

        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                insideParen = true;
                insideCount = 0;
            } else if (c == ')') {
                insideParen = false;
            } else if (insideParen) {
                if (c != '_' && c != '(' && c != ')') {
                    insideCount++;
                }
            } else {
                if (c != '_' && c != '(' && c != ')') {
                    outsideCount++;
                } else {
                    if (outsideCount > maxOutside) {
                        maxOutside = outsideCount;
                    }
                    outsideCount = 0;
                }
            }
        }
        if (outsideCount > maxOutside) {
            maxOutside = outsideCount;
        }

        System.out.println(maxOutside + " " + insideCount);
    }
}
